#: Every payload a webhook delivers.
Payload = Union[
    ActionTaken,
    ActivityEnded,
    MessageAcked,
    MessageDelivered,
    MessageDismissed,
    MessageExpired,
    MessageUndeliverable,
    PairingCreated,
    PairingRevoked,
]

#: The events the hub sends, each with the type of its payload.
EVENT_TYPES: Dict[str, Type[Any]] = {
    "action": ActionTaken,
    "activity.ended": ActivityEnded,
    "message.acked": MessageAcked,
    "message.delivered": MessageDelivered,
    "message.dismissed": MessageDismissed,
    "message.expired": MessageExpired,
    "message.undeliverable": MessageUndeliverable,
    "pairing.created": PairingCreated,
    "pairing.revoked": PairingRevoked,
}

#: The same events, each with the reader of its payload.
EVENT_DECODERS: Dict[str, Callable[[Any], Any]] = {
    "action": from_wire_action_taken,
    "activity.ended": from_wire_activity_ended,
    "message.acked": from_wire_message_acked,
    "message.delivered": from_wire_message_delivered,
    "message.dismissed": from_wire_message_dismissed,
    "message.expired": from_wire_message_expired,
    "message.undeliverable": from_wire_message_undeliverable,
    "pairing.created": from_wire_pairing_created,
    "pairing.revoked": from_wire_pairing_revoked,
}

